{
  "summary": "2016 Subaru Impreza adaptive cruise control/forward collision avoidance unexpectedly auto-brakes for turning vehicles outside its lane, with ACC on or off, causing near rear-end collisions.",
  "group": "adas",
  "symptoms": [
    "unexpected automatic braking",
    "brakes for a vehicle turning from another lane",
    "does not recognize clear lane ahead",
    "remains locked onto the car in front",
    "near rear-end collision from following traffic",
    "repeated near misses"
  ],
  "conditions": [
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage",
    "date"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "FORWARD COLLISION AVOIDANCE: ADAPTIVE CRUISE CONTROL"
    },
    {
      "kind": "symptom",
      "quote": "the auto braking feature begins to slow and will try to stop my car"
    },
    {
      "kind": "condition",
      "quote": "if one or more cars begin to slow for a left or right turn"
    },
    {
      "kind": "condition",
      "quote": "the car in front of me turning isn't in my lane"
    },
    {
      "kind": "symptom",
      "quote": "I have a clear lane ahead and suddenly the system brakes"
    },
    {
      "kind": "symptom",
      "quote": "still locked onto the car in front, but doesn't recognize the clear road ahead"
    },
    {
      "kind": "safety",
      "quote": "I've nearly been re ended because the guy behind me wasn't thinking I would suddenly brake for nothing"
    },
    {
      "kind": "condition",
      "quote": "It happened with adaptive cruise control, and with that off, the auto braking system"
    },
    {
      "kind": "symptom",
      "quote": "I have have more near misses driving this car than with any other car I've had without the system"
    },
    {
      "kind": "safety",
      "quote": "This system is dangerous, it doesn't work like it was intended."
    }
  ]
}

